insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'writing', 'AI Writing Tools', 'AI writing tools draft proposals, emails, web copy and reports. The best ones follow a house style, write proper British English and make it easy to check facts before anything is published.', 'Check whether the vendor trains on your inputs, and set British English explicitly — many tools default to US spelling.', 0 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'writing' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'image-generation', 'AI Image Generators', 'AI image generators create illustrations, product mock-ups and social graphics from a text prompt. For business use, commercial-use licensing matters as much as image quality.', 'UK copyright law on AI-generated works is still evolving; keep records of prompts and licences for anything used in advertising.', 1 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'image-generation' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'video', 'AI Video Tools', 'AI video tools edit footage by transcript, generate presenter-led videos from scripts and cut long recordings into short clips — useful for training, marketing and support content.', 'Custom avatars or voice clones of staff need their documented consent.', 2 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'video' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'audio', 'AI Audio & Voice Tools', 'AI audio tools generate natural voiceovers, clean up recordings and power voice agents for phone support.', 'Look for a range of British accents, and never clone a voice without consent.', 3 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'audio' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'music', 'AI Music Generators', 'AI music tools create royalty-free background tracks for videos, podcasts and ads.', 'Confirm the licence covers broadcast and paid advertising in the UK.', 4 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'music' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'coding', 'AI Coding Assistants', 'AI coding assistants write, explain and review code inside your editor or terminal, helping small technical teams ship faster.', 'Check whether code is retained or used for training before using client code.', 5 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'coding' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'marketing', 'AI Marketing Tools', 'AI marketing tools help with campaign copy, social content, ad variants and audience research — as long as a human stays in charge of the final message.', 'Marketing emails to individuals and sole traders fall under PECR consent rules.', 6 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'marketing' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'seo', 'AI SEO Tools', 'AI SEO tools research keywords, audit websites and help plan content — including visibility in AI answer engines.', 'Make sure the tool has a dedicated UK database — US volumes mislead UK businesses.', 7 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'seo' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'sales', 'AI Sales Tools', 'AI sales tools draft follow-ups, summarise calls, score leads and flag deals at risk.', 'Prospect data is personal data under UK GDPR — record your lawful basis.', 8 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'sales' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'customer-support', 'AI Customer Support Tools', 'AI support agents answer routine questions from your help content and hand complex cases to people.', 'Tell customers when they are talking to AI and offer a route to a human.', 9 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'customer-support' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'productivity', 'AI Productivity & Assistants', 'General AI assistants and productivity tools — ChatGPT, Claude, Gemini, Copilot and workflow automation — that save time across everyday office work.', 'Business plans usually exclude your data from model training; consumer plans may not.', 10 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'productivity' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'research', 'AI Research Tools', 'AI research tools search the web and your documents and answer with citations you can check.', 'For UK regulation, favour answers that cite GOV.UK, HMRC or the ICO directly.', 11 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'research' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'education', 'AI Tools for Education & Training', 'AI tools that create lessons, quizzes and training material, and help staff and learners study.', 'Schools and trainers must check age-appropriate design and DfE guidance before using AI with learners.', 12 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'education' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'presentation', 'AI Presentation Makers', 'AI presentation makers turn an outline or document into a designed deck in minutes.', 'Many UK procurement teams still require editable PowerPoint files — check export quality.', 13 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'presentation' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'design', 'AI Design Tools', 'AI design tools produce social graphics, flyers and brand assets quickly without a designer for every job.', 'Check commercial licensing of AI-generated images before using them in paid ads.', 14 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'design' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'finance', 'AI Finance Tools', 'AI finance tools read receipts and invoices, categorise transactions and forecast cash flow.', 'Anything feeding your tax returns should sit on HMRC-recognised Making Tax Digital software.', 15 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'finance' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'legal', 'AI Legal Tools', 'AI legal tools summarise contracts, flag risky clauses and draft first versions of documents — never a substitute for qualified advice.', 'Check the tool understands English/Scots law differences and SRA guidance if you are a regulated firm.', 16 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'legal' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'healthcare', 'AI Tools for Healthcare', 'AI tools for clinics and practices: note-taking, scheduling and patient communications.', 'Health data is special category data — a DPIA and suitable NHS/DSPT compliance are usually required.', 17 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'healthcare' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'ecommerce', 'AI Tools for Ecommerce', 'AI tools for online shops: product descriptions, image editing, customer chat and store analytics.', 'Product claims must comply with UK consumer protection law — review AI copy before publishing.', 18 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'ecommerce' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'ai-tools', 'social-media', 'AI Social Media Tools', 'AI social media tools plan, write and schedule posts and repurpose long content into short formats.', 'Label paid partnerships in line with ASA/CAP guidance.', 19 where not exists (select 1 from categories where root = 'ai-tools' and slug = 'social-media' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'accounting', 'Accounting Software', 'Accounting software handles invoicing, bank reconciliation, VAT and reporting. For UK businesses, HMRC recognition for Making Tax Digital is essential — for VAT now, and for Income Tax as MTD for ITSA rolls out from April 2026.', 'Check the specific MTD service (VAT or Income Tax) the product is recognised for on GOV.UK.', 20 where not exists (select 1 from categories where root = 'software' and slug = 'accounting' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'crm', 'CRM Software', 'CRM software keeps every lead, customer and deal in one place so enquiries don''t slip through the cracks.', 'Record consent and lawful basis; check EU/UK hosting options.', 21 where not exists (select 1 from categories where root = 'software' and slug = 'crm' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'project-management', 'Project Management Software', 'Project management tools plan work, assign tasks and track progress across teams and clients.', 'For client work, check guest-access pricing and where files are stored.', 22 where not exists (select 1 from categories where root = 'software' and slug = 'project-management' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'hr', 'HR Software', 'HR software manages employee records, holiday, absence, onboarding and performance.', 'Look for UK holiday-entitlement rules, right-to-work records and UK GDPR retention controls.', 23 where not exists (select 1 from categories where root = 'software' and slug = 'hr' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'payroll', 'Payroll Software', 'Payroll software calculates pay, tax and pensions and submits Real Time Information (RTI) to HMRC.', 'Use HMRC-recognised payroll software; check auto-enrolment support for The Pensions Regulator.', 24 where not exists (select 1 from categories where root = 'software' and slug = 'payroll' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'marketing', 'Marketing Software', 'Marketing platforms bring together email, landing pages, forms, social and analytics.', 'PECR governs electronic marketing; build consent capture into every form.', 25 where not exists (select 1 from categories where root = 'software' and slug = 'marketing' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'seo', 'SEO Software', 'SEO software researches keywords, audits sites, tracks rankings and analyses competitors.', 'Choose a tool with a UK database and local rank tracking.', 26 where not exists (select 1 from categories where root = 'software' and slug = 'seo' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'email-marketing', 'Email Marketing Software', 'Email marketing software builds lists, designs campaigns and automates sequences.', 'Double opt-in and clear unsubscribe links help you meet PECR and UK GDPR.', 27 where not exists (select 1 from categories where root = 'software' and slug = 'email-marketing' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'customer-support', 'Customer Support Software', 'Customer support platforms combine a shared inbox, help centre, chat and increasingly AI agents.', 'Check data-hosting region and how AI conversations are stored.', 28 where not exists (select 1 from categories where root = 'software' and slug = 'customer-support' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'helpdesk', 'Helpdesk & Ticketing Software', 'Helpdesk software turns emails and messages into tickets with owners, priorities and SLAs.', 'EU/UK data residency is often an add-on — check before buying.', 29 where not exists (select 1 from categories where root = 'software' and slug = 'helpdesk' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'erp', 'ERP Software', 'ERP systems combine finance, inventory, purchasing and operations for growing businesses.', 'Confirm UK VAT, MTD and multi-currency support.', 30 where not exists (select 1 from categories where root = 'software' and slug = 'erp' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'inventory', 'Inventory Management Software', 'Inventory software tracks stock across warehouses and sales channels.', 'Check integrations with UK couriers and marketplaces.', 31 where not exists (select 1 from categories where root = 'software' and slug = 'inventory' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'pos', 'POS Systems', 'Point-of-sale systems take payments in person and sync sales with stock and accounts.', 'Compare UK card-processing fees, not just subscription prices.', 32 where not exists (select 1 from categories where root = 'software' and slug = 'pos' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'ecommerce', 'Ecommerce Platforms', 'Ecommerce platforms run your online shop: products, checkout, payments and fulfilment.', 'Configure UK VAT and Consumer Contracts Regulations information correctly.', 33 where not exists (select 1 from categories where root = 'software' and slug = 'ecommerce' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'website-builders', 'Website Builders', 'Website builders let you launch a professional site without a developer.', 'Add a UK-compliant cookie banner and privacy notice.', 34 where not exists (select 1 from categories where root = 'software' and slug = 'website-builders' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'automation', 'Workflow Automation Software', 'Workflow automation software connects the apps you already use so that routine jobs run on their own: a web enquiry becomes a CRM contact, a signed quote creates an invoice, a new starter gets their accounts set up. Newer platforms add AI steps that read, classify and draft as part of the flow.', 'Automations copy personal data between systems — record each flow in your UK GDPR record of processing and check where the platform stores run logs.', 35 where not exists (select 1 from categories where root = 'software' and slug = 'automation' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'analytics', 'Analytics Software', 'Analytics software measures website traffic, conversions and customer behaviour.', 'Analytics cookies generally need consent under PECR unless the tool is cookie-less.', 36 where not exists (select 1 from categories where root = 'software' and slug = 'analytics' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'cybersecurity', 'Cybersecurity Software', 'Cybersecurity tools protect accounts, devices and data — password managers, endpoint protection and backup.', 'The NCSC''s Cyber Essentials scheme is a sensible baseline for UK SMEs.', 37 where not exists (select 1 from categories where root = 'software' and slug = 'cybersecurity' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'communication', 'Team Communication Tools', 'Team chat and communication tools keep conversations and files organised across a business.', 'Set message-retention policies that match your UK GDPR retention schedule.', 38 where not exists (select 1 from categories where root = 'software' and slug = 'communication' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'video-conferencing', 'Video Conferencing & Meeting Tools', 'Video conferencing and AI meeting tools host calls, record them and produce summaries and actions.', 'Tell participants when calls are recorded and check where recordings are stored.', 39 where not exists (select 1 from categories where root = 'software' and slug = 'video-conferencing' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'document-management', 'Document Management & Knowledge Base Software', 'Document and knowledge tools store policies, SOPs and files so teams can find answers quickly.', 'Map retention periods for personal data held in documents.', 40 where not exists (select 1 from categories where root = 'software' and slug = 'document-management' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'legal', 'Legal Software', 'Legal software for practice management, e-signature and contract management.', 'Regulated firms should check SRA and data-security requirements.', 41 where not exists (select 1 from categories where root = 'software' and slug = 'legal' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'education', 'Education Software', 'Software for schools, tutors and training providers: learning platforms, course builders and admin.', 'Children''s data needs extra care under the ICO''s Age Appropriate Design Code.', 42 where not exists (select 1 from categories where root = 'software' and slug = 'education' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'restaurant', 'Restaurant & Hospitality Software', 'Software for restaurants, cafés and pubs: POS, bookings, ordering and staff rotas.', 'Allergen information must meet UK Food Information Regulations.', 43 where not exists (select 1 from categories where root = 'software' and slug = 'restaurant' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'real-estate', 'Real Estate & Property Software', 'Software for estate and letting agents and landlords: CRM, listings, compliance and property management.', 'Listings must carry accurate material information; lettings need deposit and right-to-rent compliance.', 44 where not exists (select 1 from categories where root = 'software' and slug = 'real-estate' and parent_id is null);
insert into categories (root, slug, name, intro, uk_notes, sort_order) select 'software', 'construction', 'Construction & Trades Software', 'Job-management software for builders and tradespeople: quotes, scheduling, job sheets and invoicing.', 'Check Construction Industry Scheme (CIS) support if you use subcontractors.', 45 where not exists (select 1 from categories where root = 'software' and slug = 'construction' and parent_id is null);
