insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'chatgpt-vs-claude', least(a.id, b.id), greatest(a.id, b.id), 'ChatGPT and Claude are both leading general AI assistants with similar entry pricing. Claude is strongest at long documents, contract review and natural British English; ChatGPT has the broader feature set — image generation, voice mode, custom GPTs and the largest integration ecosystem.', case when a.id < b.id then array['You want one tool for writing, images, voice and data analysis','Your team already knows ChatGPT','You plan to build custom GPTs for repeatable tasks']::text[] else array['Client-facing writing and tone matter most','You review contracts, policies or long reports','You want Projects that hold company knowledge for every chat']::text[] end, case when a.id < b.id then array['Client-facing writing and tone matter most','You review contracts, policies or long reports','You want Projects that hold company knowledge for every chat']::text[] else array['You want one tool for writing, images, voice and data analysis','Your team already knows ChatGPT','You plan to build custom GPTs for repeatable tasks']::text[] end, 'published' from products a, products b where a.slug = 'chatgpt' and b.slug = 'claude' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'gemini-vs-microsoft-365-copilot', least(a.id, b.id), greatest(a.id, b.id), 'Each assistant works best inside its own office suite: Microsoft 365 Copilot inside Outlook, Word, Excel and Teams; Gemini inside Gmail, Docs, Sheets and Meet, where it is often included in the Workspace plan.', case when a.id < b.id then array['You run on Google Workspace','You want AI included in your existing plan','You do lots of research']::text[] else array['You run on Microsoft 365 and Teams','You need strong compliance controls','Meetings dominate your week']::text[] end, case when a.id < b.id then array['You run on Microsoft 365 and Teams','You need strong compliance controls','Meetings dominate your week']::text[] else array['You run on Google Workspace','You want AI included in your existing plan','You do lots of research']::text[] end, 'published' from products a, products b where a.slug = 'gemini' and b.slug = 'microsoft-365-copilot' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'chatgpt-vs-gemini', least(a.id, b.id), greatest(a.id, b.id), 'ChatGPT offers the broader standalone feature set and ecosystem. Gemini is built into Google Workspace, is often included in Workspace plans and has strong research features.', case when a.id < b.id then array['You want the most capable standalone assistant','You don''t use Google Workspace','You want custom GPTs']::text[] else array['You use Gmail, Docs and Sheets daily','You want AI included in your existing plan','You do document-heavy research']::text[] end, case when a.id < b.id then array['You use Gmail, Docs and Sheets daily','You want AI included in your existing plan','You do document-heavy research']::text[] else array['You want the most capable standalone assistant','You don''t use Google Workspace','You want custom GPTs']::text[] end, 'published' from products a, products b where a.slug = 'chatgpt' and b.slug = 'gemini' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'quickbooks-vs-xero', least(a.id, b.id), greatest(a.id, b.id), 'Both are HMRC-recognised Making Tax Digital platforms with AI-assisted bookkeeping and similar entry pricing. Xero is very widely used by UK accountants and has a large app marketplace; QuickBooks is known for its mobile app and frequent introductory offers.', case when a.id < b.id then array['You''re a sole trader managing books on your phone','You want MTD for Income Tax made simple','You like intro discounts']::text[] else array['You work with an accountant or bookkeeper','You need lots of integrations','You''re VAT-registered and growing']::text[] end, case when a.id < b.id then array['You work with an accountant or bookkeeper','You need lots of integrations','You''re VAT-registered and growing']::text[] else array['You''re a sole trader managing books on your phone','You want MTD for Income Tax made simple','You like intro discounts']::text[] end, 'published' from products a, products b where a.slug = 'quickbooks' and b.slug = 'xero' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'make-vs-zapier', least(a.id, b.id), greatest(a.id, b.id), 'Zapier is the easier of the two to learn and connects the most apps. Make offers a visual builder suited to complex logic, is typically cheaper at high volumes and offers EU hosting.', case when a.id < b.id then array['You run high volumes','You need branching and data transformation','You prefer EU data hosting']::text[] else array['You''re new to automation','You need an obscure app integration','Speed of setup matters most']::text[] end, case when a.id < b.id then array['You''re new to automation','You need an obscure app integration','Speed of setup matters most']::text[] else array['You run high volumes','You need branching and data transformation','You prefer EU data hosting']::text[] end, 'published' from products a, products b where a.slug = 'make' and b.slug = 'zapier' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'fathom-vs-fireflies', least(a.id, b.id), greatest(a.id, b.id), 'Fathom has a generous free plan and concise summaries. Fireflies focuses on searchable call history and conversation analytics for sales teams.', case when a.id < b.id then array['You want great free meeting notes','You value concise summaries']::text[] else array['You run a sales team','You want to search across every call']::text[] end, case when a.id < b.id then array['You run a sales team','You want to search across every call']::text[] else array['You want great free meeting notes','You value concise summaries']::text[] end, 'published' from products a, products b where a.slug = 'fathom' and b.slug = 'fireflies' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'chatgpt-vs-microsoft-365-copilot', least(a.id, b.id), greatest(a.id, b.id), 'Microsoft 365 Copilot works inside Outlook, Teams and SharePoint using your own work data. ChatGPT is a standalone assistant with a broader feature set that isn''t tied to one office suite.', case when a.id < b.id then array['You use Google Workspace or a mix of tools','You want images, voice and custom GPTs','Budget per person matters most']::text[] else array['Your business runs on Microsoft 365 and Teams','Meetings and email dominate your week','You need enterprise compliance controls']::text[] end, case when a.id < b.id then array['Your business runs on Microsoft 365 and Teams','Meetings and email dominate your week','You need enterprise compliance controls']::text[] else array['You use Google Workspace or a mix of tools','You want images, voice and custom GPTs','Budget per person matters most']::text[] end, 'published' from products a, products b where a.slug = 'chatgpt' and b.slug = 'microsoft-365-copilot' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'claude-vs-gemini', least(a.id, b.id), greatest(a.id, b.id), 'Claude is strongest for writing, contracts and long documents. Gemini is built into Google Workspace, is often included in the plan and has strong research features.', case when a.id < b.id then array['Client-facing writing matters most','You review contracts and long reports','You use Microsoft 365 or mixed tools']::text[] else array['You run on Google Workspace','You want AI included in your plan','You do lots of research']::text[] end, case when a.id < b.id then array['You run on Google Workspace','You want AI included in your plan','You do lots of research']::text[] else array['Client-facing writing matters most','You review contracts and long reports','You use Microsoft 365 or mixed tools']::text[] end, 'published' from products a, products b where a.slug = 'claude' and b.slug = 'gemini' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'canva-vs-gamma', least(a.id, b.id), greatest(a.id, b.id), 'Gamma focuses on generating and restructuring presentations quickly. Canva is an all-round design platform covering social, print, video and presentations.', case when a.id < b.id then array['You need one design tool for everything','Your Brand Kit is already in Canva','You create lots of social content']::text[] else array['Presentations are the main job','You start from documents or outlines','You want share links with analytics']::text[] end, case when a.id < b.id then array['Presentations are the main job','You start from documents or outlines','You want share links with analytics']::text[] else array['You need one design tool for everything','Your Brand Kit is already in Canva','You create lots of social content']::text[] end, 'published' from products a, products b where a.slug = 'canva' and b.slug = 'gamma' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
insert into comparisons (slug, product_a_id, product_b_id, intro, choose_a_if, choose_b_if, status) select 'hubspot-vs-pipedrive', least(a.id, b.id), greatest(a.id, b.id), 'HubSpot offers a free CRM with marketing, sales and service tools in one platform. Pipedrive focuses on a simple, visual sales pipeline with predictable per-seat pricing.', case when a.id < b.id then array['You want to start free','You need marketing and service too','You want AI agents']::text[] else array['You run a small B2B sales team','You want the simplest pipeline','You prefer predictable per-seat pricing']::text[] end, case when a.id < b.id then array['You run a small B2B sales team','You want the simplest pipeline','You prefer predictable per-seat pricing']::text[] else array['You want to start free','You need marketing and service too','You want AI agents']::text[] end, 'published' from products a, products b where a.slug = 'hubspot' and b.slug = 'pipedrive' on conflict (slug) do update set intro = excluded.intro, choose_a_if = excluded.choose_a_if, choose_b_if = excluded.choose_b_if;
